fn parse_int(s: &str) -> Option<Int> {
    match s.chars().nth(0) {
        Some('0'..='9') => {
            let mut num = 0;
            for c in s.chars() {
                num = num * 10 + (c as Int - '0' as Int);
            }
            Some(num)
        }
        _ => None
    }
}

